<script setup>
import { onMounted, onBeforeUnmount, ref } from 'vue';
import * as echarts from 'echarts';
import { ElMessage } from 'element-plus';
const props=defineProps({api:{type:Function,required:true}});
const speed=ref(null),activity=ref(null),mode=ref(null);let charts=[],observer;
const names={beginner:'新手入门','english-word':'英文单词','english-phrase':'英文语句','english-article':'英文文章','pinyin-syllable':'拼音音节','pinyin-word':'拼音词组','pinyin-article':'拼音文章',battle:'占领战',boss:'淘汰赛',race:'打字赛车',rhythm:'字母音游',runner:'遗迹逃亡',challenge:'一分钟挑战'};
onMounted(async()=>{try{const data=await props.api('/api/admin/progress/overview');const daily=data.daily||[], dates=daily.map(x=>x.date.slice(5));charts=[echarts.init(speed.value),echarts.init(activity.value),echarts.init(mode.value)];const common={tooltip:{trigger:'axis'},grid:{left:45,right:20,top:20,bottom:28},xAxis:{type:'category',data:dates},yAxis:{type:'value',min:0}};charts[0].setOption({...common,color:['#1f9d61'],series:[{type:'line',smooth:true,data:daily.map(x=>x.speed||0),areaStyle:{opacity:.1}}]});charts[1].setOption({...common,color:['#2e86de'],series:[{type:'bar',data:daily.map(x=>x.sessions||0),barMaxWidth:20}]});const modes=Object.entries(data.modes||{}).map(([key,value])=>({name:names[key]||key,value}));charts[2].setOption({tooltip:{trigger:'item'},legend:{bottom:0,type:'scroll'},series:[{type:'pie',radius:['42%','70%'],center:['50%','44%'],data:modes.length?modes:[{name:'暂无训练',value:1}]}]});observer=new ResizeObserver(()=>charts.forEach(x=>x.resize()));charts.forEach(x=>observer.observe(x.getDom()));}catch(e){ElMessage.error(e.message)}});onBeforeUnmount(()=>{observer?.disconnect();charts.forEach(x=>x.dispose())});
</script>
<template><div class="chart-grid"><section><h2>速度趋势</h2><p>近 14 天学生平均训练速度</p><div ref="speed" class="chart"></div></section><section><h2>训练活动</h2><p>每天完成的练习记录</p><div ref="activity" class="chart"></div></section><section class="wide"><h2>训练模式分布</h2><p>查看学生主要使用哪些训练内容</p><div ref="mode" class="chart"></div></section></div></template>
<style scoped>.chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:18px}.chart-grid section{padding:20px;background:#fff;border:1px solid #e5ece7;border-radius:12px;min-width:0}.chart-grid .wide{grid-column:1 / -1}.chart-grid h2{font-size:17px;margin:0}.chart-grid p{color:#75867d;font-size:13px}.chart{height:250px}@media(max-width:900px){.chart-grid{grid-template-columns:1fr}.chart-grid .wide{grid-column:auto}}</style>
